/**
 * "Add a company": validating the two steps, building the new company record
 * and folding the user's answers into its `userReported` figures.
 *
 * Three places run this code: the form (to show field errors), the mock API in
 * the browser, and the Vite dev-server plugin that writes the new company into
 * `src/mocks/data/companies.json`. So it stays pure and uses relative imports -
 * the plugin loads it outside the app's aliases.
 */
import {
  LEAVE_DURATION_OPTIONS,
  PARENTAL_SUPPORT_OPTIONS,
  PROMOTION_CYCLE_OPTIONS,
  PROMOTION_SUPPORT_OPTIONS,
  PROMOTION_TIME_OPTIONS,
  ROLE_OPTIONS,
  US_STATE_OPTIONS,
  WELFARE_BENEFIT_OPTIONS,
  WOMEN_SUPPORT_OPTIONS,
} from '../config/formOptions.js';
import {
  INDUSTRIES,
  SENIORITY_LEVELS,
  type Industry,
  type SeniorityLevel,
} from '../types/common.js';
import type {
  BenefitsAnswers,
  CompanyDataAnswers,
  MaternityAnswers,
  NewCompanyDetails,
  NewCompanyInput,
  PromotionAnswers,
  SalaryAnswers,
  StoredCompanySubmission,
  WomenSupportAnswers,
  YesNoNotSure,
} from '../types/companySubmission.js';
import type {
  CompanyRecord,
  CompanyUserReported,
  DiversityField,
  ReportedBenefit,
} from '../types/demoSearch.js';
import { containsBannedWord } from './moderation.js';
import { normalizeCompanyName } from './text.js';

export const NEW_COMPANY_LIMITS = {
  nameMax: 80,
  salaryUsd: { min: 10_000, max: 1_000_000 },
  teamSize: { min: 1, max: 10_000 },
  percent: { min: 0, max: 100 },
  wellnessUsd: { min: 0, max: 10_000 },
} as const;

/** Keyed by the dotted field path, e.g. `company.name` or `salary.annualSalaryUsd`. */
export type NewCompanyFieldErrors = Record<string, string[]>;

export type Validation<T> =
  { ok: true; value: T } | { ok: false; fieldErrors: NewCompanyFieldErrors };

type Raw = Record<string, unknown>;

function asObject(value: unknown): Raw {
  return typeof value === 'object' && value !== null ? (value as Raw) : {};
}

function oneOf<T extends string>(
  errors: NewCompanyFieldErrors,
  field: string,
  value: unknown,
  options: readonly T[],
  message: string,
): T {
  if (typeof value === 'string' && (options as readonly string[]).includes(value))
    return value as T;
  errors[field] = [message];
  return options[0] as T;
}

function bool(errors: NewCompanyFieldErrors, field: string, value: unknown): boolean {
  if (typeof value !== 'boolean') errors[field] = ['Choose yes or no.'];
  return value === true;
}

const ANSWERS: readonly YesNoNotSure[] = ['yes', 'no', 'not_sure'];

function tri(errors: NewCompanyFieldErrors, field: string, value: unknown): YesNoNotSure {
  return oneOf(errors, field, value, ANSWERS, 'Choose yes, no or not sure.');
}

/** A number in range, or `null` when `optional` and left out ("N/A"). */
function num(
  errors: NewCompanyFieldErrors,
  field: string,
  value: unknown,
  range: { readonly min: number; readonly max: number },
  optional: boolean,
): number | null {
  if (value === null || value === undefined) {
    if (!optional) errors[field] = ['Enter a number.'];
    return null;
  }
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    errors[field] = [optional ? 'Enter a number, or N/A.' : 'Enter a number.'];
    return null;
  }
  if (value < range.min || value > range.max) {
    errors[field] = [
      `Enter a number from ${range.min.toLocaleString('en-US')} to ${range.max.toLocaleString('en-US')}.`,
    ];
  }
  return value;
}

/** The ticked boxes that are real options, each once. */
function picks(value: unknown, options: readonly string[]): string[] {
  const raw = Array.isArray(value) ? value : [];
  return options.filter((option) => raw.includes(option));
}

/** `example.com` or `https://example.com/jobs` -> `https://example.com/jobs`; empty stays empty. */
export function normalizeWebsite(raw: string): string {
  const trimmed = raw.trim();
  if (!trimmed) return '';
  return /^https?:\/\//i.test(trimmed) ? trimmed : `https://${trimmed}`;
}

function isWebsite(url: string): boolean {
  return /^https?:\/\/[a-z0-9-]+(\.[a-z0-9-]+)+(:\d+)?(\/\S*)?$/i.test(url);
}

/** Step 1: name, website, industry and headquarters state. */
export function validateCompanyDetails(input: unknown): Validation<NewCompanyDetails> {
  const body = asObject(input);
  const errors: NewCompanyFieldErrors = {};
  const name = typeof body.name === 'string' ? body.name.trim().replace(/\s+/g, ' ') : '';
  const website = normalizeWebsite(typeof body.website === 'string' ? body.website : '');

  if (!name) errors['company.name'] = ['Please input the company name.'];
  else if (name.length > NEW_COMPANY_LIMITS.nameMax)
    errors['company.name'] = [`Keep the name under ${NEW_COMPANY_LIMITS.nameMax} characters.`];
  else if (containsBannedWord(name))
    errors['company.name'] = ['This name contains a word that isn’t allowed. Please change it.'];

  if (website && !isWebsite(website))
    errors['company.website'] = ['Enter a web address, e.g. example.com.'];

  const industry = oneOf<Industry>(
    errors,
    'company.industry',
    body.industry,
    INDUSTRIES,
    'Select an industry.',
  );
  const state = oneOf(
    errors,
    'company.state',
    body.state,
    US_STATE_OPTIONS,
    'Select a U.S. state.',
  );

  return Object.keys(errors).length > 0
    ? { ok: false, fieldErrors: errors }
    : { ok: true, value: { name, website, industry, state } };
}

/** Step 2: the five boxes. Promotion, benefits and maternity may be `null` (skipped). */
export function validateCompanyData(input: unknown): Validation<CompanyDataAnswers> {
  const body = asObject(input);
  const errors: NewCompanyFieldErrors = {};
  const { percent } = NEW_COMPANY_LIMITS;

  const s = asObject(body.salary);
  const salary: SalaryAnswers = {
    role: oneOf(errors, 'salary.role', s.role, ROLE_OPTIONS, 'Select a role.'),
    level: oneOf<SeniorityLevel>(
      errors,
      'salary.level',
      s.level,
      SENIORITY_LEVELS,
      'Select a level.',
    ),
    state: oneOf(errors, 'salary.state', s.state, US_STATE_OPTIONS, 'Select a U.S. state.'),
    annualSalaryUsd: Math.round(
      num(
        errors,
        'salary.annualSalaryUsd',
        s.annualSalaryUsd,
        NEW_COMPANY_LIMITS.salaryUsd,
        false,
      ) ?? 0,
    ),
  };

  const w = asObject(body.womenSupport);
  const teamSize = num(
    errors,
    'womenSupport.teamSize',
    w.teamSize,
    NEW_COMPANY_LIMITS.teamSize,
    true,
  );
  const womenOnTeam = num(
    errors,
    'womenSupport.womenOnTeam',
    w.womenOnTeam,
    { min: 0, max: NEW_COMPANY_LIMITS.teamSize.max },
    true,
  );
  if (teamSize !== null && womenOnTeam !== null && womenOnTeam > teamSize) {
    errors['womenSupport.womenOnTeam'] = ['Can’t be more than the team size.'];
  }
  const womenSupport: WomenSupportAnswers = {
    teamSize: teamSize === null ? null : Math.round(teamSize),
    womenOnTeam: womenOnTeam === null ? null : Math.round(womenOnTeam),
    hasWomanManager: bool(errors, 'womenSupport.hasWomanManager', w.hasWomanManager),
    issuesHandledSeriously: tri(
      errors,
      'womenSupport.issuesHandledSeriously',
      w.issuesHandledSeriously,
    ),
    support: picks(w.support, WOMEN_SUPPORT_OPTIONS),
  };

  let promotion: PromotionAnswers | null = null;
  if (body.promotion != null) {
    const p = asObject(body.promotion);
    promotion = {
      timeToPromotion: oneOf(
        errors,
        'promotion.timeToPromotion',
        p.timeToPromotion,
        PROMOTION_TIME_OPTIONS.map((option) => option.label),
        'Select a time.',
      ),
      cycle: oneOf(errors, 'promotion.cycle', p.cycle, PROMOTION_CYCLE_OPTIONS, 'Select a cycle.'),
      lastPromotionTransparent: bool(
        errors,
        'promotion.lastPromotionTransparent',
        p.lastPromotionTransparent,
      ),
      promotionsFair: tri(errors, 'promotion.promotionsFair', p.promotionsFair),
      support: picks(p.support, PROMOTION_SUPPORT_OPTIONS),
    };
  }

  let benefits: BenefitsAnswers | null = null;
  if (body.benefits != null) {
    const b = asObject(body.benefits);
    benefits = {
      healthInsurancePct: num(
        errors,
        'benefits.healthInsurancePct',
        b.healthInsurancePct,
        percent,
        true,
      ),
      wellnessBudgetUsdPerMonth: num(
        errors,
        'benefits.wellnessBudgetUsdPerMonth',
        b.wellnessBudgetUsdPerMonth,
        NEW_COMPANY_LIMITS.wellnessUsd,
        true,
      ),
      usesWellnessBudget: bool(errors, 'benefits.usesWellnessBudget', b.usesWellnessBudget),
      feelSupported: tri(errors, 'benefits.feelSupported', b.feelSupported),
      welfare: picks(b.welfare, WELFARE_BENEFIT_OPTIONS),
    };
  }

  let maternity: MaternityAnswers | null = null;
  if (body.maternity != null) {
    const m = asObject(body.maternity);
    maternity = {
      leaveDuration: oneOf(
        errors,
        'maternity.leaveDuration',
        m.leaveDuration,
        LEAVE_DURATION_OPTIONS.map((option) => option.label),
        'Select a duration.',
      ),
      payPercent: num(errors, 'maternity.payPercent', m.payPercent, percent, true),
      returnToWorkSupport: bool(errors, 'maternity.returnToWorkSupport', m.returnToWorkSupport),
      feelSupported: tri(errors, 'maternity.feelSupported', m.feelSupported),
      support: picks(m.support, PARENTAL_SUPPORT_OPTIONS),
    };
  }

  return Object.keys(errors).length > 0
    ? { ok: false, fieldErrors: errors }
    : { ok: true, value: { salary, womenSupport, promotion, benefits, maternity } };
}

/** Both steps together, as `POST /demo/companies` receives them. */
export function validateNewCompany(input: unknown): Validation<NewCompanyInput> {
  const body = asObject(input);
  const company = validateCompanyDetails(body.company);
  const data = validateCompanyData(body.data);
  if (company.ok && data.ok)
    return { ok: true, value: { company: company.value, data: data.value } };
  return {
    ok: false,
    fieldErrors: {
      ...(company.ok ? {} : company.fieldErrors),
      ...(data.ok ? {} : data.fieldErrors),
    },
  };
}

/** The company already listed under this name (ignoring case, punctuation, "Inc" and so on). */
export function findSameCompany<T extends { name: string }>(
  name: string,
  companies: readonly T[],
): T | undefined {
  const target = normalizeCompanyName(name);
  return companies.find((company) => normalizeCompanyName(company.name) === target);
}

/** `Brightfern Health` -> `brightfern-health`, made unique against `taken`. */
export function companyIdFor(name: string, taken: readonly string[]): string {
  const base =
    name
      .toLowerCase()
      .normalize('NFKD')
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '')
      .slice(0, 60) || 'company';
  let id = base;
  for (let n = 2; taken.includes(id); n += 1) id = `${base}-${n}`;
  return id;
}

/** A company added by a user: their details, nothing published yet, and their answers folded in. */
export function buildNewCompany(
  input: NewCompanyInput,
  id: string,
  submission: Omit<StoredCompanySubmission, 'answers'>,
): CompanyRecord {
  const { company, data } = input;
  const empty: CompanyUserReported = {
    salary: null,
    promotion: null,
    diversity: null,
    maternity: null,
    benefits: null,
  };
  return {
    id,
    name: company.name,
    website: company.website,
    intro: '',
    industry: company.industry,
    mainFocus: [],
    location: company.state,
    email: '',
    phone: '',
    address: '',
    contacts: [],
    sources: [],
    dataCollectedAt: submission.submittedAt.slice(0, 10),
    verification: {
      status: 'unverified',
      checkedBy: 'ai',
      checkedAt: null,
      confidence: null,
      notes: 'Added by a SHIP member. Not checked yet.',
    },
    salary: null,
    promotion: null,
    womenSupport: null,
    benefits: [],
    paidMaternityLeave: null,
    userReported: applyCompanyData(empty, data),
    submissions: [{ ...submission, answers: data }],
  };
}

function round1(value: number): number {
  return Math.round(value * 10) / 10;
}

/** Folds `next` into an average over `count` earlier values. */
function addToAverage(previous: number | null, count: number, next: number, digits = 1): number {
  const value = previous === null || count === 0 ? next : (previous * count + next) / (count + 1);
  const factor = 10 ** digits;
  return Math.round(value * factor) / factor;
}

function countBenefits(
  items: ReportedBenefit[] | null,
  names: readonly string[],
): ReportedBenefit[] {
  const next = (items ?? []).map((item) => ({ ...item }));
  for (const name of names) {
    const existing = next.find((item) => item.name.toLowerCase() === name.toLowerCase());
    if (existing) existing.reports += 1;
    else next.push({ name, reports: 1 });
  }
  return next.sort((a, b) => b.reports - a.reports || a.name.localeCompare(b.name));
}

/**
 * Returns `current` with one person's answers added. Only the figures the
 * company page shows are updated; skipped sections and N/A numbers leave
 * their figures alone (`fieldCounts` tracks how many reports each one has).
 */
export function applyCompanyData(
  current: CompanyUserReported,
  data: CompanyDataAnswers,
): CompanyUserReported {
  const next: CompanyUserReported = { ...current };

  const salary = current.salary;
  const salaryCount = salary?.submissions ?? 0;
  next.salary = {
    submissions: salaryCount + 1,
    averageAnnualUsd: addToAverage(
      salary?.averageAnnualUsd ?? null,
      salaryCount,
      data.salary.annualSalaryUsd,
      0,
    ),
  };

  const diversity = current.diversity;
  const n = diversity?.submissions ?? 0;
  const count = (field: DiversityField) => diversity?.fieldCounts?.[field] ?? n;
  const { teamSize, womenOnTeam } = data.womenSupport;
  const womenPct =
    teamSize !== null && womenOnTeam !== null && teamSize > 0
      ? (womenOnTeam / teamSize) * 100
      : null;
  next.diversity = {
    submissions: n + 1,
    womanManagerPct: addToAverage(
      diversity?.womanManagerPct ?? null,
      count('womanManagerPct'),
      data.womenSupport.hasWomanManager ? 100 : 0,
    ),
    womanInCSuitePct: diversity?.womanInCSuitePct ?? null,
    womenOnTeamPct:
      womenPct === null
        ? (diversity?.womenOnTeamPct ?? null)
        : addToAverage(
            diversity?.womenOnTeamPct ?? null,
            count('womenOnTeamPct'),
            round1(womenPct),
          ),
    feelIncludedPct: diversity?.feelIncludedPct ?? null,
    fieldCounts: {
      womanManagerPct: count('womanManagerPct') + 1,
      womanInCSuitePct: count('womanInCSuitePct'),
      womenOnTeamPct: count('womenOnTeamPct') + (womenPct === null ? 0 : 1),
      feelIncludedPct: count('feelIncludedPct'),
    },
  };

  if (data.promotion) {
    const promotion = current.promotion;
    const months =
      PROMOTION_TIME_OPTIONS.find((option) => option.label === data.promotion?.timeToPromotion)
        ?.months ?? 0;
    next.promotion = {
      submissions: (promotion?.submissions ?? 0) + 1,
      avgMonthsToPromotion: addToAverage(
        promotion?.avgMonthsToPromotion ?? null,
        promotion?.submissions ?? 0,
        months,
      ),
    };
  }

  if (data.maternity) {
    const maternity = current.maternity;
    const m = maternity?.submissions ?? 0;
    const weeksCount = maternity?.fieldCounts?.avgPaidWeeks ?? m;
    const payCount = maternity?.fieldCounts?.avgPayPercent ?? m;
    const weeks =
      LEAVE_DURATION_OPTIONS.find((option) => option.label === data.maternity?.leaveDuration)
        ?.weeks ?? 0;
    const pay = data.maternity.payPercent;
    next.maternity = {
      submissions: m + 1,
      avgPaidWeeks: addToAverage(maternity?.avgPaidWeeks ?? null, weeksCount, weeks),
      avgPayPercent:
        pay === null
          ? (maternity?.avgPayPercent ?? null)
          : addToAverage(maternity?.avgPayPercent ?? null, payCount, pay),
      fieldCounts: {
        avgPaidWeeks: weeksCount + 1,
        avgPayPercent: payCount + (pay === null ? 0 : 1),
      },
    };
  }

  if (data.benefits) {
    const benefits = current.benefits;
    next.benefits = {
      submissions: (benefits?.submissions ?? 0) + 1,
      items: countBenefits(benefits?.items ?? null, data.benefits.welfare),
    };
  }

  return next;
}
